const body = $input.first().json;
const jobs = Array.isArray(body && body.data) ? body.data : [];
const nowSec = Math.floor(Date.now() / 1000);
const cutoff = nowSec - 24 * 60 * 60;
const AI_KEYWORDS = /\bai\b|artificial intelligence|automation|machine learning|ml engineer|\bllm\b|\bnlp\b|generative ai/i;
const GERMAN_TITLE_MARKERS = /m\/w\/d/i;
const GERMAN_WORD_RE = /\b(und|der|die|das|f\u00fcr|mit|wir|sie)\b/gi;
function stripHtml(value) {
  return String(value || '').replace(/<[^>]*>/g, ' ').replace(/&[a-z#0-9]+;/gi, ' ').replace(/\s+/g, ' ').trim();
}
function germanWordCount(text) {
  const found = String(text || '').match(GERMAN_WORD_RE);
  return found ? found.length : 0;
}
function toUnixSeconds(value) {
  if (value === null || value === undefined) return 0;
  if (typeof value === 'number') return value > 1e12 ? Math.floor(value / 1000) : Math.floor(value);
  const parsed = Date.parse(String(value));
  return Number.isNaN(parsed) ? 0 : Math.floor(parsed / 1000);
}
const matched = [];
for (const job of jobs) {
  if (!job || job.remote !== true) continue;
  const rawCreated = job['created_at (unix timestamp seconds)'] !== undefined ? job['created_at (unix timestamp seconds)'] : job.created_at;
  const createdSec = toUnixSeconds(rawCreated);
  if (!createdSec || createdSec < cutoff) continue;
  const title = String(job.title || '');
  const tagText = Array.isArray(job.tags) ? job.tags.join(' ') : String(job.tags || '');
  if (!AI_KEYWORDS.test(title) && !AI_KEYWORDS.test(tagText)) continue;
  if (GERMAN_TITLE_MARKERS.test(title)) continue;
  const cleanDescription = stripHtml(job.description);
  if (germanWordCount(cleanDescription.slice(0, 1200)) >= 5) continue;
  matched.push({ title: title, company: job.company_name || 'Unknown company', location: job.location || 'Remote', url: job.url || '', tags: Array.isArray(job.tags) ? job.tags.slice(0, 6).join(', ') : '', snippet: cleanDescription.slice(0, 100) });
}
if (matched.length === 0) {
  return [{ json: { noJobs: true, checkedJobs: jobs.length } }];
}
return matched.map(function (job) { return { json: job }; });

const items = $input.all().map(function (item) { return item.json; });
const isNoJobs = items.length === 1 && items[0] && items[0].noJobs === true;
const embed = {
  title: '\ud83e\udd16 AI Automation Jobs - Daily Digest',
  color: 5814783,
  footer: { text: 'Source: Arbeitnow' },
  timestamp: new Date().toISOString()
};
if (isNoJobs) {
  embed.description = 'No new remote AI/Automation jobs were posted in the last 24 hours. Check back tomorrow!';
  embed.color = 15105570;
} else {
  embed.fields = items.map(function (job) {
    const valueLines = ['**' + (job.company || 'Unknown company') + '** \u00b7 ' + (job.location || 'Remote'), '[Apply](' + (job.url || '') + ')'];
    if (job.snippet) valueLines.push('> ' + job.snippet);
    return { name: job.title || 'Untitled role', value: valueLines.join('\n'), inline: false };
  });
}
return [{ json: { discordPayload: { username: 'Job Scout', embeds: [embed] }, jobCount: isNoJobs ? 0 : items.length } }];
